# Helper function to check if a node matches problematic patterns
check_problematic_node(node) {
    node.ir_type == "Attribute"
    node.name == "protocol"
    node.value.ir_type == "String"
    node.value.value == "http"
} else {
    node.ir_type == "Attribute"
    node.name == "disable_tls"
    node.value.ir_type == "Boolean"
    node.value.value == true
} else {
    node.ir_type == "Attribute"
    node.name == "enable_ssl"
    node.value.ir_type == "Boolean"
    node.value.value == false
} else {
    node.ir_type == "Attribute"
    node.name == "checksum"
    node.value.ir_type == "String"
    node.value.value == "disabled"
} else {
    node.ir_type == "Attribute"
    node.name == "hash_verification"
    node.value.ir_type == "Boolean"
    node.value.value == false
} else {
    node.ir_type == "Attribute"
    node.name == "encryption"
    node.value.ir_type == "String"
    node.value.value == "disabled"
} else {
    node.ir_type == "Attribute"
    node.name == "signature_algorithm"
    node.value.ir_type == "String"
    node.value.value == "none"
} else {
    node.ir_type == "Attribute"
    node.name == "mutual_tls"
    node.value.ir_type == "Boolean"
    node.value.value == false
} else {
    node.ir_type == "Attribute"
    node.name == "validate_certs"
    node.value.ir_type == "Boolean"
    node.value.value == false
} else {
    node.ir_type == "Attribute"
    node.name == "gpgcheck"
    node.value.ir_type == "Integer"
    node.value.value == 0
}

# Helper function to traverse and find problematic nodes in complex values
find_problematic_nodes(node, path) = matches {
    matches := {m |
        walk(node, [p, n])
        check_problematic_node(n)
        m := {"node": n, "full_path": array.concat(path, p)}
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check atomic units
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Find problematic nodes within this atomic unit
    problematic := find_problematic_nodes(node, ["atomic_unit"])
    count(problematic) > 0
    p := problematic[_]

    result := {
        "type": "sec_no_int_check",
        "element": p.node,
        "path": parent.path,
        "description": "Missing integrity check detected (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables (for nested configurations like Ansible repo configs)
    variables := glitch_lib.all_variables(parent)
    var_node := variables[_]

    # Find problematic nodes within this variable's value
    problematic := find_problematic_nodes(var_node, ["variable"])
    count(problematic) > 0
    p := problematic[_]

    result := {
        "type": "sec_no_int_check",
        "element": p.node,
        "path": parent.path,
        "description": "Missing integrity check detected (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all attributes (including nested ones)
    all_attrs := glitch_lib.all_attributes(parent)
    attr := all_attrs[_]

    # Check this attribute directly
    check_problematic_node(attr)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing integrity check detected (CWE-353)"
    }
}

