package glitch

import data.glitch_lib

url_attributes := {"url", "source", "baseurl", "mirrorlist"}

check_url(value) {
    value.ir_type == "String"
    regex.match("^(http|ftp)://", value.value)
} else {
    value.ir_type == "Sum"
    walk(value, [path, node])
    node.ir_type == "String"
    regex.match("^(http|ftp)://", node.value)
}

check_problematic_key_value(key, value) {
    key == "protocol"
    value.ir_type == "String"
    value.value == "http"
} else {
    key == "disable_tls"
    value.ir_type == "Boolean"
    value.value == true
} else {
    key == "enable_ssl"
    value.ir_type == "Boolean"
    value.value == false
} else {
    key == "checksum"
    value.ir_type == "String"
    value.value == "disabled"
} else {
    key == "hash_verification"
    value.ir_type == "Boolean"
    value.value == false
} else {
    key == "encryption"
    value.ir_type == "String"
    value.value == "disabled"
} else {
    key == "signature_algorithm"
    value.ir_type == "String"
    value.value == "none"
} else {
    key == "mutual_tls"
    value.ir_type == "Boolean"
    value.value == false
} else {
    key == "validate_certs"
    value.ir_type == "String"
    value.value == "no"
} else {
    key == "validate_certs"
    value.ir_type == "Boolean"
    value.value == false
} else {
    key == "gpgcheck"
    value.ir_type == "Integer"
    value.value == 0
} else {
    key == "gpgcheck"
    value.ir_type == "String"
    value.value == "0"
} else {
    url_attributes[_] == key
    check_url(value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    check_problematic_key_value(attr.name, attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing integrity check detected (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var_node := variables[_]
    walk(var_node.value, [path, node])
    node.ir_type == "KeyValue"
    key := node.name
    value := node.value
    check_problematic_key_value(key, value)

    result := {
        "type": "sec_no_int_check",
        "element": var_node,
        "path": parent.path,
        "description": "Missing integrity check detected in variable (CWE-353)"
    }
}

